css:
.engagesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2c3a3f;
    background: linear-gradient(160deg, #f4faf8 0%, #eef5f6 55%, #e9f1f3 100%);
    border-radius: 18px;
}

.engagesim-container * {
    box-sizing: border-box;
}

.engagesim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f766e 0%, #15897e 55%, #2aa79b 100%);
    color: #f3fffb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 14px 34px rgba(15, 118, 110, 0.28);
}

.engagesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.engagesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #d6fff4;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.32);
    padding: 5px 14px;
    border-radius: 999px;
}

.engagesim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6fff8;
}

.engagesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #51686d;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.engagesim-period-counter #currentDay,
.engagesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f766e;
}

.engagesim-round-name {
    background: rgba(15, 118, 110, 0.12);
    color: #0f766e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.engagesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b4530a;
    background: rgba(244, 132, 38, 0.14);
    border: 1px solid rgba(244, 132, 38, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.engagesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.engagesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d7e8e6;
    box-shadow: 0 6px 18px rgba(38, 70, 66, 0.08);
    border-top: 4px solid #2aa79b;
}

.engagesim-card-engage { border-top-color: #0f766e; }
.engagesim-card-attrition { border-top-color: #e0533b; }
.engagesim-card-csat { border-top-color: #f48426; }
.engagesim-card-renewal { border-top-color: #3b7dd8; }

.engagesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a8086;
}

.engagesim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16302e;
    font-variant-numeric: tabular-nums;
}

.engagesim-card-engage .engagesim-value { color: #0f766e; }
.engagesim-card-attrition .engagesim-value { color: #e0533b; }
.engagesim-card-csat .engagesim-value { color: #d76f14; }
.engagesim-card-renewal .engagesim-value { color: #3b7dd8; }

.engagesim-sublabel {
    font-size: 0.76rem;
    color: #7f9499;
    line-height: 1.35;
}

.engagesim-engage-strong { border-top-color: #0f9e5e; }
.engagesim-engage-strong .engagesim-value { color: #0f9e5e; }
.engagesim-engage-weak { border-top-color: #e0533b; }
.engagesim-engage-weak .engagesim-value { color: #e0533b; }

.engagesim-attrition-good { border-top-color: #0f9e5e; }
.engagesim-attrition-good .engagesim-value { color: #0f9e5e; }
.engagesim-attrition-bad { border-top-color: #c5341d; }
.engagesim-attrition-bad .engagesim-value { color: #c5341d; }

.engagesim-renewal-strong .engagesim-value { color: #0f9e5e; }
.engagesim-renewal-strong { border-top-color: #0f9e5e; }

.engagesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d7e8e6;
    color: #2c3a3f;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(38, 70, 66, 0.06);
}

.engagesim-budget-bar #budgetDisplay {
    font-size: 1.08rem;
    letter-spacing: 0.3px;
    color: #0f766e;
}

.engagesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #0f766e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(38, 70, 66, 0.08);
}

.engagesim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.engagesim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #134e4a;
    margin-bottom: 6px;
}

.engagesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #41565b;
}

.engagesim-briefing-text strong { color: #0f766e; }
.engagesim-briefing-text em { color: #b4530a; font-style: italic; }

.engagesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d7e8e6;
    box-shadow: 0 6px 18px rgba(38, 70, 66, 0.08);
}

.engagesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #134e4a;
    border-bottom: 2px solid #e3efed;
    padding-bottom: 8px;
}

.engagesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3a3f;
    margin: 14px 0 6px;
}

.engagesim-container select,
.engagesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c5dbd8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fcfb;
    color: #1f3330;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.engagesim-container select:focus,
.engagesim-container input[type="number"]:focus {
    outline: none;
    border-color: #0f766e;
    box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.16);
}

.engagesim-container select option {
    background-color: #ffffff;
    color: #1f3330;
}

.engagesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0f766e;
}

.engagesim-range-readout,
.engagesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #51686d;
    margin-top: 4px;
}

.engagesim-range-readout span:nth-child(2),
.engagesim-alloc-readout span:nth-child(2) {
    color: #0f766e;
    font-weight: 800;
}

.engagesim-hint {
    font-size: 0.8rem;
    color: #7f9499;
    margin-top: 8px;
    line-height: 1.45;
    background: #f4faf8;
    border: 1px dashed #c5dbd8;
    border-radius: 8px;
    padding: 8px 12px;
}

.engagesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.engagesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7fcfb;
    border: 1px solid #d7e8e6;
    border-radius: 9px;
    padding: 8px 12px;
}

.engagesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c3a3f;
}

.engagesim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.engagesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.engagesim-container .btn-primary {
    background: linear-gradient(135deg, #0f766e 0%, #2aa79b 100%);
    border: none;
    color: #ffffff;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(15, 118, 110, 0.30);
}

.engagesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.engagesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c5dbd8;
    color: #51686d;
    background: transparent;
}

.engagesim-coach {
    background: linear-gradient(160deg, #fff8f1 0%, #fdf1e6 100%);
    color: #4a3a2c;
    border: 1px solid #f3d9bf;
    border-left: 5px solid #f48426;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(180, 83, 10, 0.08);
}

.engagesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b4530a;
    margin-bottom: 8px;
}

.engagesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3a2c;
}

.engagesim-coach-body strong { color: #b4530a; }
.engagesim-coach-body em { color: #0f766e; font-style: italic; }

.engagesim-history,
.engagesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d7e8e6;
    box-shadow: 0 6px 18px rgba(38, 70, 66, 0.08);
}

.engagesim-history h3,
.engagesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #134e4a;
}

.engagesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c3a3f;
}

.engagesim-container table#usfHistoryTable th {
    background: #f4faf8;
    color: #0f766e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d7e8e6;
}

.engagesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e3efed;
    color: #41565b;
}

.engagesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fcfb;
}

.engagesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .engagesim-container {
        padding: 14px;
    }
    .engagesim-header h1 {
        font-size: 1.7rem;
    }
    .engagesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .engagesim-value {
        font-size: 2.05rem;
    }
    .engagesim-clock {
        margin-left: 0;
    }
    .engagesim-period-counter {
        font-size: 0.88rem;
    }
    .engagesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .engagesim-alloc-row {
        flex-wrap: wrap;
    }
    .engagesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .engagesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0: completion debrief card (append-only, self-contained) ── */
.eg-cm { font-family: inherit; color: #2c3a3f; padding: 4px 2px 2px; }
.eg-cm-scoreblock { text-align: center; padding: 14px 12px 16px; background: linear-gradient(160deg,#f7fcfb,#d7e8e6); border-radius: 14px; border: 1px solid #c5dbd8; }
.eg-cm-scorenum { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #0f766e; }
.eg-cm-scoremax { font-size: 1.15rem; font-weight: 600; color: #6a857f; margin-left: 2px; }
.eg-cm-scorelabel { font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: #6a857f; margin-top: 6px; }
.eg-cm-grade { font-size: 1.16rem; font-weight: 700; color: #14403a; margin-top: 8px; }
.eg-cm-badge { display: inline-block; margin-top: 10px; padding: 4px 14px; border-radius: 999px; font-size: .78rem; font-weight: 700; }
.eg-cm-badge-pass { background: #cfeee0; color: #0b6b45; }
.eg-cm-badge-miss { background: #f8ddd6; color: #b23a22; }
.eg-cm-roi { margin-top: 10px; font-size: .82rem; color: #14403a; }
.eg-cm-kpis { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; margin: 16px 0 4px; }
.eg-cm-kpi { background: #ffffff; border: 1px solid #d7e8e6; border-top: 3px solid #0f766e; border-radius: 10px; padding: 12px 8px; text-align: center; }
.eg-cm-k-engage { border-top-color: #0f766e; }
.eg-cm-k-attrition { border-top-color: #e0533b; }
.eg-cm-k-csat { border-top-color: #f48426; }
.eg-cm-k-renewal { border-top-color: #3b7dd8; }
.eg-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #2c3a3f; line-height: 1.05; }
.eg-cm-k-engage .eg-cm-kpi-val { color: #0f766e; }
.eg-cm-k-attrition .eg-cm-kpi-val { color: #e0533b; }
.eg-cm-k-csat .eg-cm-kpi-val { color: #b4530a; }
.eg-cm-k-renewal .eg-cm-kpi-val { color: #3b7dd8; }
.eg-cm-kpi-label { font-size: .74rem; font-weight: 700; color: #3f4f54; margin-top: 5px; }
.eg-cm-kpi-sub { font-size: .64rem; color: #84968f; margin-top: 2px; line-height: 1.25; }
.eg-cm-insights { margin: 16px 2px 6px; }
.eg-cm-insights h6 { font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; color: #6a857f; margin: 0 0 8px; font-weight: 700; }
.eg-cm-insights ul { margin: 0; padding-left: 18px; }
.eg-cm-insights li { font-size: .86rem; line-height: 1.5; color: #2b3a3f; margin-bottom: 7px; }
.eg-cm-footer { margin-top: 14px; padding-top: 10px; border-top: 1px solid #d7e8e6; font-size: .72rem; color: #84968f; text-align: center; font-style: italic; }
@media (max-width: 640px) { .eg-cm-kpis { grid-template-columns: repeat(2,1fr); } .eg-cm-scorenum { font-size: 2.6rem; } }

