(function() {
    'use strict';

    class EngageAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Engage to Win`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Liffey Connect Group).
            this.FUND = 1.8;                 // EUR 1.8M one-off people-investment fund
            this.RECURRING = 0.6;            // EUR 0.6M/year gated on a measurement plan
            this.REPLACEMENT_COST = 9500;    // EUR fully-loaded cost per frontline leaver
            this.ATRISK_REVENUE = 32;        // EUR 32M insurer contract at renewal
            this.MENU_SIZE = 5;              // number of intervention lines
            this.EVEN_SHARE = 0.36;          // 1.8M / 5 — the "to be fair" trap allocation

            // Concept truths (the data-supported answers).
            this.TRUE_DRIVER = `managers`;
            this.TRUE_SEGMENT = `atrisk`;
            this.TRUE_LEADING = `pulse`;
            this.TRUE_CONTROL = `phased`;
            this.TRUE_ROI = `avoided`;
            this.TRUE_HEADLINE = `retention`;
            this.TRUE_NARRATIVE = `integrated`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engage: 58,              // group engagement score (was 74; bottom quartile 44)
                    attrition: 41,           // at-risk-team attrition % (benchmark ~25; lower better)
                    csat: 71,                // insurer-account CSAT % (was 84)
                    renewal: 25,             // board & client confidence in the people case (0-100)
                    budgetUsed: 0,           // EUR M of the 1.8M fund committed
                    spreadThin: false,       // funded everything equally — no measurable signal
                    volunteerTrap: false,    // volunteering-led while pay/workload ignored
                    noBaseline: false,       // claimed ROI with no baseline/control
                    vanityMetrics: false,    // dashboard of activity metrics
                    costOnly: false,         // stripped the responsible-leadership story
                    engageHistory: [58],
                    attritionHistory: [41],
                    csatHistory: [71],
                    renewalHistory: [25],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win. Notably the R2 allocation
                // seeds the "spread thin to be fair" trap.
                state.decisions = {
                    driver: `managers`,
                    segment: `allstaff`,
                    causal: 50,
                    managers: 0.3,
                    pay: 0.3,
                    volunteer: 0.3,
                    redesign: 0.3,
                    recognition: 0.6,
                    leading: `hours`,
                    control: `baseline`,
                    roi: `engagement`,
                    horizon: 6,
                    headline: `engagement`,
                    narrative: `costonly`,
                    cfo: `brand`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dr = document.getElementById(`driverInput`);
                const sg = document.getElementById(`segmentInput`);
                const ca = document.getElementById(`causalInput`);
                if (dr) decisions.driver = dr.value;
                if (sg) decisions.segment = sg.value;
                if (ca) decisions.causal = parseInt(ca.value, 10);
                if (!Number.isFinite(decisions.causal) || decisions.causal < 0 || decisions.causal > 100) {
                    warn(`warn_causal_range`); return false;
                }
            } else if (round === 2) {
                const ids = [`managersInput`, `payInput`, `volunteerInput`, `redesignInput`, `recognitionInput`];
                const keys = [`managers`, `pay`, `volunteer`, `redesign`, `recognition`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0) * 100) / 100;
                if (Math.abs(total - this.FUND) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const ld = document.getElementById(`leadingInput`);
                const ct = document.getElementById(`controlInput`);
                const ro = document.getElementById(`roiInput`);
                const ho = document.getElementById(`horizonInput`);
                if (ld) decisions.leading = ld.value;
                if (ct) decisions.control = ct.value;
                if (ro) decisions.roi = ro.value;
                if (ho) decisions.horizon = parseInt(ho.value, 10);
                if (!Number.isFinite(decisions.horizon) || decisions.horizon < 1 || decisions.horizon > 24) {
                    warn(`warn_horizon_range`); return false;
                }
            } else if (round === 4) {
                const hd = document.getElementById(`headlineInput`);
                const na = document.getElementById(`narrativeInput`);
                const cf = document.getElementById(`cfoInput`);
                const cv = document.getElementById(`convictionInput`);
                if (hd) decisions.headline = hd.value;
                if (na) decisions.narrative = na.value;
                if (cf) decisions.cfo = cf.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let engageDelta = 0, attritionDelta = 0, csatDelta = 0, renewalDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose past the headline score (Common Error: treat one uniform problem).
                switch (d.driver) {
                    case `managers`: engageDelta += 6; renewalDelta += 8; coachKey = `coach_r1_managers`; break;
                    case `pay`: engageDelta += 3; renewalDelta += 4; coachKey = `coach_r1_pay`; break;
                    case `purpose`: engageDelta += 2; renewalDelta += 1; coachKey = `coach_r1_purpose`; break;
                    case `score`: renewalDelta -= 4; coachKey = `coach_r1_score`; break;
                }

                // Target the segment that moves the renewal-relevant metrics.
                switch (d.segment) {
                    case `atrisk`: renewalDelta += 8; csatDelta += 2; if (d.driver === `managers`) coachKey = `coach_r1_sharp`; break;
                    case `allstaff`: renewalDelta -= 2; coachKey = `coach_r1_allstaff`; break;
                    case `topteams`: renewalDelta -= 4; coachKey = `coach_r1_topteams`; break;
                    case `newhires`: renewalDelta -= 2; break;
                }

                // Causal-link confidence (you must defend cause vs coincidence).
                if (d.causal >= 60 && d.causal <= 85) { renewalDelta += 5; }
                else if (d.causal > 85) { renewalDelta += 2; coachKey = `coach_r1_overconfident`; }
                else if (d.causal <= 25) { renewalDelta -= 4; coachKey = `coach_r1_undersure`; }

                summaryKey = (d.driver === `managers` && d.segment === `atrisk`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate the EUR 1.8M fund — concentration beats dilution.
                const mgr = d.managers, pay = d.pay, vol = d.volunteer, rd = d.redesign, rec = d.recognition;
                spend = Math.round((mgr + pay + vol + rd + rec) * 100) / 100;

                // Causal levers (manager capability + the at-risk team's pay/workload) carry the load.
                engageDelta += mgr * 9 + rd * 5 + vol * 3 + rec * 2;
                attritionDelta -= pay * 7 + mgr * 4 + rd * 2;            // pay/workload + managers cut attrition
                csatDelta += mgr * 3 + pay * 2 + rd * 1;
                renewalDelta += mgr * 3 + pay * 4;

                // Volunteering builds purpose only when pay/workload on the at-risk team is also funded.
                if (vol >= 0.4 && pay >= 0.3) { engageDelta += vol * 3; renewalDelta += 2; }
                // The "community party while service stays broken" trap.
                if (vol >= 0.5 && pay < 0.2) {
                    ds.volunteerTrap = true; engageDelta -= 2; renewalDelta -= 6; csatDelta -= 2;
                    coachKey = `coach_r2_volunteertrap`;
                }

                // Concentration test: a near-even spread produces no measurable signal.
                const parts = [mgr, pay, vol, rd, rec];
                const maxShare = Math.max.apply(null, parts);
                const spread = parts.filter((v) => Math.abs(v - this.EVEN_SHARE) <= 0.12).length;
                if (spread >= 4 || maxShare < 0.45) {
                    ds.spreadThin = true;
                    engageDelta = Math.round(engageDelta * 0.4 * 10) / 10;   // signal lost in the noise
                    attritionDelta = Math.round(attritionDelta * 0.4 * 10) / 10;
                    renewalDelta -= 6;
                    if (!ds.volunteerTrap) coachKey = `coach_r2_spreadthin`;
                } else if (mgr >= 0.5 && pay >= 0.4 && (mgr + pay) >= 1.0) {
                    // Concentrated on the data-supported levers.
                    renewalDelta += 5; engageDelta += 3;
                    if (!ds.volunteerTrap) coachKey = `coach_r2_concentrated`;
                } else if (coachKey === `coach_default`) {
                    coachKey = `coach_r2_mixed`;
                }

                summaryKey = ds.spreadThin ? `sum_r2_spread` :
                             ds.volunteerTrap ? `sum_r2_volunteer` :
                             (mgr >= 0.5 && pay >= 0.4) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Design the measurement plan — leading vs lagging, baseline, control, ROI.
                switch (d.leading) {
                    case `pulse`: renewalDelta += 9; coachKey = `coach_r3_pulse`; break;
                    case `csatnow`: renewalDelta += 1; coachKey = `coach_r3_csatnow`; break;
                    case `hours`: ds.vanityMetrics = true; renewalDelta -= 8; coachKey = `coach_r3_vanity`; break;
                }

                switch (d.control) {
                    case `phased`: renewalDelta += 9; break;
                    case `baseline`: renewalDelta += 2; break;
                    case `none`: ds.noBaseline = true; renewalDelta -= 8; if (!ds.vanityMetrics) coachKey = `coach_r3_nobaseline`; break;
                }

                switch (d.roi) {
                    case `avoided`: renewalDelta += 8; if (d.leading === `pulse` && d.control === `phased`) coachKey = `coach_r3_sharp`; break;
                    case `engagement`: renewalDelta -= 2; break;
                    case `activity`: ds.vanityMetrics = true; renewalDelta -= 6; coachKey = `coach_r3_vanity`; break;
                }

                // A credible horizon: lagging metrics lag. Too short = naive, way too long = no signal in time.
                if (d.horizon >= 4 && d.horizon <= 9) { renewalDelta += 4; }
                else if (d.horizon <= 2) { renewalDelta -= 4; coachKey = `coach_r3_horizonshort`; }
                else if (d.horizon >= 18) { renewalDelta -= 2; }

                summaryKey = (d.leading === `pulse` && d.control === `phased` && d.roi === `avoided`) ? `sum_r3_good` :
                             (ds.vanityMetrics ? `sum_r3_vanity` : ds.noBaseline ? `sum_r3_nobaseline` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the plan to the CFO and the client.
                switch (d.headline) {
                    case `retention`: renewalDelta += 10; csatDelta += 2; coachKey = `coach_r4_retention`; break;
                    case `engagement`: renewalDelta += 3; coachKey = `coach_r4_engagement`; break;
                    case `hours`: ds.vanityMetrics = true; renewalDelta -= 8; coachKey = `coach_r4_hours`; break;
                }

                switch (d.narrative) {
                    case `integrated`: renewalDelta += 10; engageDelta += 2; coachKey = `coach_r4_integrated`; break;
                    case `costonly`: ds.costOnly = true; renewalDelta -= 4; engageDelta -= 2; coachKey = `coach_r4_costonly`; break;
                    case `purposeonly`: renewalDelta -= 6; coachKey = `coach_r4_purposeonly`; break;
                }

                switch (d.cfo) {
                    case `measured`: renewalDelta += 8; if (d.narrative === `integrated` && d.headline === `retention`) coachKey = `coach_r4_facedown`; break;
                    case `brand`: renewalDelta -= 4; break;
                    case `cut`: engageDelta -= 2; renewalDelta -= 2; coachKey = `coach_r4_cut`; break;
                }

                if (d.conviction >= 60) { renewalDelta += 4; }
                else if (d.conviction <= 25) { renewalDelta -= 4; }

                summaryKey = (d.headline === `retention` && d.narrative === `integrated` && d.cfo === `measured`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: meter the EUR 1.8M one-off fund (committed in Round 2).
            ds.budgetUsed = Math.min(this.FUND, Math.round((ds.budgetUsed + spend) * 100) / 100);

            // Apply deltas, clamped (engagement/csat/renewal 0-100; attrition floored at the ~25% benchmark).
            ds.engage = Math.max(0, Math.min(100, Math.round((ds.engage + engageDelta) * 10) / 10));
            ds.attrition = Math.max(20, Math.min(60, Math.round((ds.attrition + attritionDelta) * 10) / 10));
            ds.csat = Math.max(0, Math.min(100, Math.round((ds.csat + csatDelta) * 10) / 10));
            ds.renewal = Math.max(0, Math.min(100, Math.round(ds.renewal + renewalDelta)));

            ds.engageHistory.push(ds.engage);
            ds.attritionHistory.push(ds.attrition);
            ds.csatHistory.push(ds.csat);
            ds.renewalHistory.push(ds.renewal);
            // ── v1.1.0 fix: persist the composite where Express reporting reads it ──
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            const composite = this._composite(ds);
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;


            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                engage: ds.engage,
                engageDelta: Math.round(engageDelta * 10) / 10,
                attrition: ds.attrition,
                attritionDelta: Math.round(attritionDelta * 10) / 10,
                csat: ds.csat,
                csatDelta: Math.round(csatDelta * 10) / 10,
                renewal: ds.renewal,
                renewalDelta: Math.round(renewalDelta),
                budgetUsed: ds.budgetUsed,
                score: composite,
                spreadThin: ds.spreadThin,
                volunteerTrap: ds.volunteerTrap,
                vanityMetrics: ds.vanityMetrics,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR: English "€1.80M" (symbol before), Spanish "1,80 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(2)}M`;
        }

        _fmtPct(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            const txt = (lang === `es`) ? n.toFixed(1).replace(`.`, `,`) : n.toFixed(1);
            return `${txt}%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`engageDisplay`, `domainState.engage`, (v) => {
                const card = document.querySelector(`.engagesim-card-engage`);
                if (card) {
                    card.classList.toggle(`engagesim-engage-strong`, Number(v) >= 70);
                    card.classList.toggle(`engagesim-engage-weak`, Number(v) < 55);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`attritionDisplay`, `domainState.attrition`, (v) => {
                const card = document.querySelector(`.engagesim-card-attrition`);
                if (card) {
                    card.classList.toggle(`engagesim-attrition-good`, Number(v) <= 28);
                    card.classList.toggle(`engagesim-attrition-bad`, Number(v) >= 38);
                }
                return self._fmtPct(Number(v));
            });
            uiManager.bind(`csatDisplay`, `domainState.csat`, (v) => self._fmtPct(Number(v)));
            uiManager.bind(`renewalDisplay`, `domainState.renewal`, (v) => {
                const card = document.querySelector(`.engagesim-card-renewal`);
                if (card) card.classList.toggle(`engagesim-renewal-strong`, Number(v) >= 70);
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.FUND);
            });

            // Causal-confidence slider readout.
            const ca = document.getElementById(`causalInput`);
            const caReadout = document.getElementById(`causalReadout`);
            if (ca && caReadout) {
                caReadout.textContent = ca.value;
                ca.addEventListener(`input`, function() { caReadout.textContent = ca.value; });
            }

            // Fund live total (must hit EUR 1.8M).
            const allocIds = [`managersInput`, `payInput`, `volunteerInput`, `redesignInput`, `recognitionInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (allocReadout) allocReadout.textContent = total.toFixed(2);
                const bar = document.querySelector(`.engagesim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.FUND) > 0.001) ? `#e0533b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

