        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const engage = Math.round(ds.engage);
            const attrition = Math.round(ds.attrition * 10) / 10;
            const csat = Math.round(ds.csat * 10) / 10;
            const renewal = Math.round(ds.renewal);

            // Avoided-attrition euros: every point off the at-risk team's attrition is real money.
            // ~310 roles on the at-risk account × points avoided × EUR 9,500 replacement cost.
            const pointsAvoided = Math.max(0, 41 - attrition);
            const avoidedEurosM = Math.round((310 * (pointsAvoided / 100) * this.REPLACEMENT_COST / 1e6) * 100) / 100;

            // Composite: engagement, low attrition, CSAT and renewal confidence.
            const composite = Math.round(
                engage * 0.25 + (100 - (attrition - 20) * (100 / 40)) * 0.20 + csat * 0.20 + renewal * 0.35
            );

            const retained = attrition <= 30;
            const engaged = engage >= 68;
            const measured = !ds.vanityMetrics && !ds.noBaseline && renewal >= 65;
            const renewed = renewal >= 70 && csat >= 78 && retained;
            const failedProof = ds.spreadThin || ds.vanityMetrics || ds.noBaseline;

            let performance = window.mySimulation.t(`grade_lost`);
            if (renewed && engaged && measured && composite >= 78) performance = window.mySimulation.t(`grade_renewed`);
            else if (retained && measured) performance = window.mySimulation.t(`grade_defended`);
            else if (ds.spreadThin) performance = window.mySimulation.t(`grade_nosignal`);
            else if (ds.volunteerTrap) performance = window.mySimulation.t(`grade_party`);
            else if (failedProof) performance = window.mySimulation.t(`grade_frozen`);
            else if (composite >= 58) performance = window.mySimulation.t(`grade_mixed`);

            const insights = [];
            if (renewed && engaged && measured) insights.push(window.mySimulation.t(`insight_renewed`));
            else if (ds.spreadThin) insights.push(window.mySimulation.t(`insight_spread`));
            else if (ds.volunteerTrap) insights.push(window.mySimulation.t(`insight_volunteer`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.vanityMetrics) insights.push(window.mySimulation.t(`insight_vanity`));
            if (ds.noBaseline) insights.push(window.mySimulation.t(`insight_nobaseline`));
            if (ds.costOnly) insights.push(window.mySimulation.t(`insight_costonly`));
            if (retained) insights.push(window.mySimulation.t(`insight_retained`));
            if (avoidedEurosM > 0) insights.push(window.mySimulation.t(`insight_roi`));

            return {
                engage: engage,
                attrition: attrition,
                csat: csat,
                renewal: renewal,
                avoidedEurosM: avoidedEurosM,
                retained: retained,
                engaged: engaged,
                measured: measured,
                renewed: renewed,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        // ── v1.1.0 fix: persist composite score + localized completion debrief ──
        _composite(ds) {
            // Verbatim mirror of getPerformanceSummary()'s composite (no scoring change).
            const engage = Math.round(ds.engage || 0);
            const attrition = Math.round((ds.attrition || 0) * 10) / 10;
            const csat = Math.round((ds.csat || 0) * 10) / 10;
            const renewal = Math.round(ds.renewal || 0);
            return Math.round(engage * 0.25 + (100 - (attrition - 20) * (100 / 40)) * 0.20 + csat * 0.20 + renewal * 0.35);
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const composite = (typeof s.composite === `number`) ? s.composite : 0;
            const grade = s.performance || ``;
            const held = composite >= 58;
            const engage = (s.engage != null) ? s.engage : 0;
            const attrition = (s.attrition != null) ? s.attrition : 0;
            const csat = (s.csat != null) ? s.csat : 0;
            const renewal = (s.renewal != null) ? s.renewal : 0;
            const roi = (s.avoidedEurosM != null) ? s.avoidedEurosM : 0;
            const insights = Array.isArray(s.insights) ? s.insights : [];

            const badgeClass = held ? `eg-cm-badge-pass` : `eg-cm-badge-miss`;
            const badgeText = held ? t(`cm_badge_beat`) : t(`cm_badge_missed`);

            const kpi = (label, val, sub, cls) => `
                <div class="eg-cm-kpi ${cls}">
                    <div class="eg-cm-kpi-val">${val}</div>
                    <div class="eg-cm-kpi-label">${label}</div>
                    <div class="eg-cm-kpi-sub">${sub}</div>
                </div>`;

            let insightHtml = ``;
            insights.forEach((it) => { insightHtml += `<li>${it}</li>`; });
            const roiLine = (roi > 0) ? `<div class="eg-cm-roi">${t(`cm_roi_label`)}: <strong>EUR ${roi}M</strong></div>` : ``;

            return `
                <div class="eg-cm">
                    <div class="eg-cm-scoreblock">
                        <div class="eg-cm-scorenum">${composite}<span class="eg-cm-scoremax">/100</span></div>
                        <div class="eg-cm-scorelabel">${t(`cm_score_label`)}</div>
                        <div class="eg-cm-grade">${grade}</div>
                        <span class="eg-cm-badge ${badgeClass}">${badgeText}</span>
                        ${roiLine}
                    </div>
                    <div class="eg-cm-kpis">
                        ${kpi(t(`engage_label`), engage, t(`engage_sub`), `eg-cm-k-engage`)}
                        ${kpi(t(`attrition_label`), attrition + `%`, t(`attrition_sub`), `eg-cm-k-attrition`)}
                        ${kpi(t(`csat_label`), csat + `%`, t(`csat_sub`), `eg-cm-k-csat`)}
                        ${kpi(t(`renewal_label`), renewal, t(`renewal_sub`), `eg-cm-k-renewal`)}
                    </div>
                    ${insightHtml ? `<div class="eg-cm-insights"><h6>${t(`cm_insights_title`)}</h6><ul>${insightHtml}</ul></div>` : ``}
                    <div class="eg-cm-footer">${t(`cm_footer`)}</div>
                </div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.spreadThin) return window.mySimulation.t(`hint_spread`);
            if (ds.volunteerTrap) return window.mySimulation.t(`hint_volunteer`);
            if (ds.vanityMetrics && state.currentPeriod >= 3) return window.mySimulation.t(`hint_vanity`);
            if (ds.noBaseline && state.currentPeriod >= 3) return window.mySimulation.t(`hint_nobaseline`);
            if (ds.attrition >= 38 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_attrition`);
            if (ds.engage >= 68 && ds.attrition <= 30 && ds.renewal >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

